const MEMBER_KEY='zhuiwu-demo-account-v1';
const packages=[{id:'basic',name:'体验会员',price:29,tokens:30000,desc:'案例资料问答 · 场景导航'},{id:'pro',name:'专业会员',price:99,tokens:150000,desc:'算法任务辅助 · 成果解读 · 报告草稿'},{id:'team',name:'团队会员',price:299,tokens:600000,desc:'多场景演示 · 团队方案展示'}];
const tokenPacks=[{id:'small',name:'轻量包',price:10,tokens:20000},{id:'medium',name:'标准包',price:50,tokens:120000},{id:'large',name:'扩展包',price:100,tokens:300000}];
function freshAccount(){return {plan:null,expires:0,balance:5000,ledger:[],messages:[]}}
let account;try{account=JSON.parse(localStorage.getItem(MEMBER_KEY));if(!account||!Number.isSafeInteger(account.balance)||account.balance<0||!Array.isArray(account.ledger)||!Array.isArray(account.messages))account=freshAccount()}catch{account=freshAccount()}
let chatBusy=false,purchasePending=null;
const fmt=n=>Number(n).toLocaleString('zh-CN');
function saveAccount(){try{localStorage.setItem(MEMBER_KEY,JSON.stringify(account))}catch{toast('浏览器存储不可用，当前会话仍可演示')}}
function membership(){return account.plan&&account.expires>Date.now()?packages.find(p=>p.id===account.plan)?.name||'体验用户':'体验用户'}
menus.push(['assistant','☏','时空智能体'],['billing','◈','会员与 Token']);topMenus.push(['assistant','时空智能体']);
function billingView(){return heading('会员与 Token','模拟会员开通与充值 · 套餐价格为演示设定','<button data-nav="assistant">进入智能体</button>')+`<section class="panel wallet"><div><span class="badge">${membership()}</span><h2>可用 Token <strong>${fmt(account.balance)}</strong></h2><p>${account.plan&&account.expires>Date.now()?'会员有效期至 '+new Date(account.expires).toLocaleDateString('zh-CN'):'体验账户获赠 5,000 模拟 Token'}</p></div><div class="note">本页面没有真实支付，也不会产生实际费用。余额仅保存在当前浏览器；模拟 Token 与任何大模型厂商的账户余额无关。</div></section><h2 class="section-title">开通会员 <small>30 天 · 含模拟 Token</small></h2><div class="catalog">${packages.map(p=>`<section class="panel card"><span class="badge">${p.id==='pro'?'答辩推荐套餐':'模拟套餐'}</span><h2>${p.name}</h2><div class="price">¥${p.price}<small> / 30天</small></div><p>${p.desc}</p><strong>${fmt(p.tokens)} 模拟 Token</strong><button class="primary" data-buy="${p.id}" data-kind="member">模拟开通</button></section>`).join('')}</div><h2 class="section-title">Token 充值 <small>模拟充值 · 一次到账</small></h2><div class="catalog">${tokenPacks.map(p=>`<section class="panel card"><h2>${p.name}</h2><strong>${fmt(p.tokens)} Token</strong><div class="price">¥${p.price}</div><button data-buy="${p.id}" data-kind="token">模拟充值</button></section>`).join('')}</div><section class="panel result-panel"><h2>账户流水</h2>${account.ledger.length?`<div class="ledger-scroll"><table><thead><tr><th>时间</th><th>项目</th><th>Token 变动</th><th>模拟金额</th><th>状态</th></tr></thead><tbody>${account.ledger.slice().reverse().slice(0,30).map(t=>`<tr><td>${escapeHTML(t.time)}</td><td>${escapeHTML(t.label)}</td><td class="${t.delta>0?'good':''}">${t.delta>0?'+':''}${fmt(t.delta)}</td><td>${t.price?'¥'+t.price:'—'}</td><td>模拟${t.delta>0?'到账':'消耗'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="subtle">暂无流水。会员开通、充值与对话消耗将在此记录。</p>'}</section>`}
function purchase(id,kind){let p=(kind==='member'?packages:tokenPacks).find(x=>x.id===id);if(!p)return;purchasePending={...p,kind,id:'DEMO-'+crypto.randomUUID()};modal(`<span class="badge">模拟订单 · 无真实付款</span><h2>${kind==='member'?'开通':'充值'}${p.name}</h2><p>订单金额：¥${p.price}（模拟）<br>到账额度：${fmt(p.tokens)} 模拟 Token${kind==='member'?'<br>会员有效期：30 天；重新开通从本次确认起计算。':''}</p><label for="demoPay">演示付款方式</label><select id="demoPay"><option>微信支付（模拟）</option><option>支付宝（模拟）</option><option>企业账户（模拟）</option></select><p class="note">点击确认只更新本浏览器中的演示账户，不会调用支付平台或真实扣款。</p><button class="primary" id="confirmDemoPay">确认模拟支付</button>`);$('#confirmDemoPay').onclick=()=>{let order=purchasePending;if(!order||account.ledger.some(t=>t.id===order.id))return;$('#confirmDemoPay').disabled=true;account.balance+=order.tokens;if(order.kind==='member'){account.plan=id;account.expires=Date.now()+30*86400000}account.ledger.push({id:order.id,label:order.name+(kind==='member'?' · 会员开通':' · Token充值'),delta:order.tokens,price:order.price,time:new Date().toLocaleString('zh-CN')});purchasePending=null;saveAccount();$('#modal').close();render();toast('模拟支付成功，'+fmt(order.tokens)+' Token 已到账')}}
function messageHTML(m){return `<div class="agent-message ${m.role==='user'?'me':''}"><span class="agent-avatar">${m.role==='user'?'张':'Λ'}</span><div><span class="subtle">${m.role==='user'?'张工':'追悟时空智能体'}</span><div class="bubble">${escapeHTML(m.text)}${m.scene?`<br><button data-nav="scene/${m.scene}">打开案例工作台</button>`:''}</div>${m.cost?`<small class="subtle">模拟消耗 ${m.cost} Token · 按文本长度估算</small>`:''}</div></div>`}
assistantView=function(){return heading('时空智能体','工业视觉与空间感知助手 · 本地资料交互演示',`<button data-nav="billing">${membership()} · ${fmt(account.balance)} Token</button>`)+`<div class="agent-layout"><section class="panel agent-chat"><div class="panel-head"><h2>追悟时空助手</h2><span class="badge">资料问答 · 模拟计费</span></div><div class="chat" id="agentChat"><div class="agent-message"><span class="agent-avatar">Λ</span><div><span class="subtle">追悟时空智能体</span><div class="bubble">你好，我可以解读案例资料、查看边坡算法最新结果，并帮你组织答辩说明。请选择一个问题，或输入你的需求。</div></div></div>${account.messages.map(messageHTML).join('')}</div><div class="suggestions">${['边坡最新结果','无人机石块识别效果','AOI指标要求','帮我组织答辩讲解'].map(q=>`<button data-prompt="${q}">${q}</button>`).join('')}</div><form class="chat-input" id="agentForm"><textarea id="agentText" rows="2" maxlength="2000" placeholder="输入问题，例如：解读最新边坡计算结果" aria-label="智能体问题"></textarea><button class="primary" id="agentSend" ${chatBusy?'disabled':''}>${chatBusy?'处理中…':'发送'}</button></form><p class="agent-foot">当前为本地资料与规则演示，未连接大语言模型。Token 消耗为估算值；边坡任务结果来自本机真实算法。</p></section><section class="panel agent-side"><span class="badge">账户概览</span><h2>${membership()}</h2><div class="token-number">${fmt(account.balance)}</div><p class="subtle">可用模拟 Token</p><button class="primary" data-nav="billing">开通会员 / 充值 Token</button><hr><h3>可用场景工具</h3>${scenes.map(s=>`<button data-nav="scene/${s.id}">${s.icon} ${s.title}<small>${s.id==='slope'?'真实算法已接入':'资料案例演示'}</small></button>`).join('')}<p class="note">智能体可提供案例入口，真实算法需要在工作台配置数据后启动。</p></section></div>`};
async function answerQuestion(text){let s=/AOI|缺陷|玻璃/i.test(text)?scenes[0]:/溜井|大块/.test(text)?scenes[1]:/无人机|石块/.test(text)?scenes[2]:/扫描|配准|激光/.test(text)?scenes[4]:/边坡|坡顶|坡脚/.test(text)?scenes[3]:null;if(s?.id==='slope'&&/最新|结果|任务|分析|解读/.test(text)){try{let d=await realFetch('/api/jobs');let j=d.jobs.find(j=>j.status==='succeeded');if(j){let c=j.result.line_counts;return {scene:'slope',text:`最新完成任务：${j.id}\n输入：${j.source==='synthetic'?'合成台阶点云（流程验证）':'本机矿区点云'}\n坡顶线 ${c.crest} 条，坡脚线 ${c.toe} 条，自动补线 ${c.auto_gap} 条。总长度 ${j.result.total_length_m} m，运行耗时 ${j.elapsed_s} 秒。\n成果包含 ENU GeoJSON、预览图和运行参数。${j.source==='synthetic'?'这证明算法流程可运行，不能作为矿区实测精度。':'线位精度需要独立检查点或人工基准验证。'}`}}}catch{}return {scene:'slope',text:'暂未读取到已完成的真实任务。可以打开边坡工作台，选择点云后运行算法。'}}if(/答辩|讲解|介绍平台/.test(text))return {text:'建议按以下顺序展示：\n1. 平台首页：统一管理工业视觉与空间感知场景。\n2. 边坡工作台：配置点云、运行真实提取与自动补线、查看成果。\n3. 智能体：资料问答与任务结果解读。\n4. 会员与 Token：展示模拟订阅、充值和对话消耗。\n说明当前边坡算法已接入；AOI与石块识别仍为资料案例，大模型问答和支付为模拟。'};if(/会员|充值|token|余额/i.test(text))return {text:`你当前是${membership()}，余额 ${fmt(account.balance)} 模拟 Token。进入“会员与 Token”可模拟开通30天会员或购买充值包。确认模拟支付后即时到账，没有真实扣费。对话消耗按文本长度估算，与你的任何大模型账户无关。`};if(s)return {scene:s.id,text:`${s.title}\n${s.desc}\n${s.facts.map(([v,n])=>n+'：'+v).join('\n')}\n${s.note}${s.id==='drone'?'\n可查看原图与识别叠加图；候选数量不等同于真实石块数。':''}`};return {text:'我目前支持五个案例资料问答、最新边坡计算结果解读、答辩流程和会员充值说明。可以问“边坡最新结果”或“无人机石块识别效果”。当前是本地交互演示，开放式大模型回答尚未接入。'}}
async function sendAgent(text){if(chatBusy||!text.trim())return;text=text.trim().slice(0,2000);chatBusy=true;if($('#agentSend')){$('#agentSend').disabled=true;$('#agentSend').textContent='处理中…'}try{let reply=await answerQuestion(text);let cost=Math.max(1,Math.ceil((text.length+reply.text.length)/2));if(account.balance<cost){modal(`<h2>模拟 Token 不足</h2><p>本次预计需要 ${cost} Token，当前余额 ${fmt(account.balance)}。充值后可继续演示。</p><button id="goRecharge" class="primary">前往模拟充值</button>`);$('#goRecharge').onclick=()=>{$('#modal').close();navigate('billing')};return}account.balance-=cost;account.messages.push({role:'user',text},{role:'assistant',text:reply.text,scene:reply.scene,cost});account.messages=account.messages.slice(-60);account.ledger.push({id:'CHAT-'+crypto.randomUUID(),label:'智能体对话',delta:-cost,price:0,time:new Date().toLocaleString('zh-CN')});saveAccount()}finally{chatBusy=false;if(activeView==='assistant')render()}}
const beforeMemberRender=render;render=function(){beforeMemberRender();if(activeView==='billing')app.innerHTML=billingView();$('#user').textContent='● 张工 · '+membership();$('#user').onclick=()=>navigate('billing');if(activeView==='assistant'){$('#agentForm').onsubmit=e=>{e.preventDefault();sendAgent($('#agentText').value)};$('#agentText').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendAgent(e.target.value)}};$('#agentChat').scrollTop=$('#agentChat').scrollHeight}};
window.removeEventListener('hashchange',beforeMemberRender);window.addEventListener('hashchange',render);document.addEventListener('click',e=>{let b=e.target.closest('[data-buy]');if(b)purchase(b.dataset.buy,b.dataset.kind);let q=e.target.closest('[data-prompt]');if(q)sendAgent(q.dataset.prompt)});render();
